func lexAll(lex func() int, data []byte) (tokens []int, spans []int) {
	buf := make([]byte, len(data)+128)
	copy(buf, data)
	input, cursor, limit, marker = buf, 0, len(buf), 0
	for {
		start := cursor
		tok := lex()
		tokens = append(tokens, tok)
		spans = append(spans, cursor-start)
		if tok == 0 || tok == -1 {
			return
		}
	}
}

